<?php
/** TEMP PS S1610 run e10b part2 (darbalaukis v3.10.4 b64 dalis 2/3) */
add_action('init', function(){
  if (!isset($_GET['ps_e10b'])) return;
  $o=array('v'=>'run e10b part2'); global $wpdb; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$wpdb->prefix}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
  $c='';
  $o['part2']=file_put_contents($bk.'/dl-v3104.part2',$c); $o['md5_part']=md5($c);
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});
